    "title": "O sistema deve listar restaurantes ativos configurados no painel administrativo.",
    "phase": "Fase 1 - MVP funcional"
  },
  {
    "id": "FR-10",
    "title": "O sistema deve disponibilizar link ou ficheiro de menu digital para cada restaurante ativo.",
    "phase": "Fase 1 - MVP funcional"
  },
  {
    "id": "FR-11",
    "title": "O sistema deve gerar um cupão ligado ao hóspede, hotel, restaurante e benefício ativo.",
    "phase": "Fase 1 - MVP funcional"
  },
